import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xhi22')
from lib import *
r=[]
r.append(R(6545769,"सेहतमंद स्नैक मिक्स — फ़ूडी रेसिपी",
"यह स्नैक मिक्स कई तरह के मेवों और बीजों से मिलने वाले पोषण और स्वस्थ वसा से भरपूर है। साथ ही फ़्रीज़-ड्राइड ब्लूबेरी मिश्रण में खट्टा-मीठा, फलों जैसा स्वाद जोड़ती हैं!",
"15","1/4 कप",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 बड़े चम्मच कम कैलोरी वाला ब्राउन शुगर विकल्प","1/8 छोटा चम्मच लाल मिर्च (केयेन)","1 कप बिना नमक के कद्दू के बीज (कच्चे, पेपिटास)","1 कप बिना नमक के सूरजमुखी के बीज","1 कप बिना नमक के पतले कटे बादाम","1/4 कप तिल","1 औंस फ़्रीज़-ड्राइड ब्लूबेरी"],
["ओवन को 300 डिग्री F पर पहले से गरम करें।","बेकिंग शीट पर नॉनस्टिक कुकिंग स्प्रे लगाएँ और एक तरफ़ रख दें।","एक कटोरे में ब्राउन शुगर विकल्प, लाल मिर्च, कद्दू के बीज, सूरजमुखी के बीज, बादाम और तिल मिलाएँ। लपेटने के लिए उछालकर मिलाएँ।","मिश्रण को बेकिंग शीट पर फैलाएँ और फिर कुकिंग स्प्रे की हल्की परत से दोबारा स्प्रे करें।","15 मिनट बेक करें, हर 5 मिनट में चलाएँ ताकि बराबर भूरा हो।","ओवन से निकालें और ठंडा होने के लिए अलग रख दें। ठंडा होने पर मेवों के मिश्रण को एक कटोरे में फ़्रीज़-ड्राइड ब्लूबेरी के साथ मिलाएँ।"]))
r.append(R(6548283,"नमकीन सीवीड एडामामे योगर्ट बाउल",
"यह नमकीन योगर्ट बाउल मलाईदार फ़ैट-फ़्री ग्रीक योगर्ट, मुलायम एडामामे और भुने हुए सीवीड के नमकीन कुरकुरेपन को मिलाकर उच्च प्रोटीन वाला, स्वाद से भरपूर स्नैक बनाता है। यह तेज़, ताज़गी भरा है और बिना किसी पकाने के सुशी से प्रेरित अलग स्वाद देता है।",
"1","1 1/2 कप",
["1 कप सादा फ़ैट-फ़्री ग्रीक योगर्ट","1 पैकेट भुना हुआ सीवीड","1/2 कप छिले हुए एडामामे"],
["एक छोटे कटोरे में 1 कप फ़ैट-फ़्री ग्रीक योगर्ट डालें।","1/2 कप छिले हुए एडामामे डालकर बराबर फैलने तक मिलाएँ।","भुने हुए सीवीड के पैकेट को ऊपर से चूरा करके डालें या नरम बनावट के लिए उसे मिला दें।","तुरंत परोसें ताकि सीवीड कुरकुरा बना रहे।"]))
r.append(R(6548471,"धनिया और नीबू के साथ काली बीन्स की टिक्कियाँ",
"क्या आप गर्मियों के लिए हल्का बर्गर ढूँढ रहे हैं? ये काली बीन्स की टिक्कियाँ साबुत अनाज के बन पर, सलाद के ऊपर या बस प्याज़ के स्लाइस के साथ प्लेट पर भी स्वादिष्ट लगती हैं।",
"10","1 (4 औंस की) टिक्की",
["1 बड़ा चम्मच जैतून का तेल","1 कप प्याज़ (कटा हुआ)","1/2 कप हरी शिमला मिर्च (कटी हुई)","1/2 कप लाल शिमला मिर्च (कटी हुई)","1 जैलापेनो मिर्च (बारीक कटी हुई)","2 कली लहसुन (बारीक कटी हुई)","1 छोटा चम्मच चिली पाउडर","1/2 छोटा चम्मच सूखा ओरेगानो","1/2 छोटा चम्मच पिसा जीरा","1 डिब्बा कम सोडियम वाली काली बीन्स (16 औंस का डिब्बा, पानी न निथारें)","1 कप ब्रेड क्रम्ब्स (बिना मसाले के)","1/4 कप, और ऊपर से छिड़कने के लिए अतिरिक्त कॉर्नमील (पीला या सफ़ेद)","1 बड़ा चम्मच नीबू का रस","1 छोटा चम्मच नीबू का छिलका (कसा हुआ)","3/4 छोटा चम्मच नमक","1/4 कप चेडर चीज़ (कम चर्बी वाला, या कम चर्बी वाला पेपर जैक चीज़ इस्तेमाल करें)","2 बड़े चम्मच धनिया पत्ती (बारीक कटी हुई)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे (स्कूप या मापने वाले कप के लिए)"],
["एक बड़े नॉनस्टिक पैन में जैतून का तेल गरम करें और प्याज़, शिमला मिर्च, लहसुन और मसाले भूनें। 3 मिनट भूनें, या जब तक सब्ज़ियाँ नरम न हो जाएँ।","काली बीन्स को उनके तरल के साथ डालें और सब्ज़ियों के साथ 1 मिनट भूनें। आँच से उतार लें। ब्रेड क्रम्ब्स, कॉर्नमील, नीबू का रस, नीबू का छिलका और नमक डालें। बीन्स के मिश्रण में से 1 कप निकालें और ब्लेंडर या फ़ूड प्रोसेसर में दरदरी प्यूरी बनने तक पीसें। प्यूरी को वापस बीन्स के मिश्रण में मिला दें। चेडर चीज़ और धनिया पत्ती डालकर अच्छी तरह मिलाएँ। मिश्रण दरदरे पेस्ट जैसा होना चाहिए और इतना सख़्त हो कि स्कूप या चम्मच में टिका रहे।","आइसक्रीम स्कूप या 1/3 कप के मापने वाले कप से 3–4 औंस के भाग बनाएँ। (मिश्रण को आसानी से निकालने के लिए आइसक्रीम स्कूप या मापने वाले कप पर कुकिंग स्प्रे की हल्की परत लगाएँ।) एक प्लेट पर कॉर्नमील छिड़कें और स्कूप किए हुए काली बीन्स के भाग प्लेट पर रखें। काली बीन्स के मिश्रण पर हल्के से कॉर्नमील छिड़कें और धीरे से दबाकर टिक्की का आकार दें।","ओवन को 375°F पर पहले से गरम करें। एक बड़े नॉनस्टिक पैन पर वनस्पति तेल का स्प्रे करें। टिक्कियों को हर तरफ़ 2 मिनट भूरा करें। अगर पैन ओवन में रखने लायक है, तो उसे ओवन में रखें और 15 मिनट या अंदर तक गरम होने तक बेक करें। या टिक्कियों को कुकी शीट पैन पर रखकर बेक करें।"]))
r.append(R(6549589,"चेरी ओट क्रिस्प",
"चेरी ओट क्रिस्प एक स्वादिष्ट मिठाई है जो मीठी और खट्टी चेरी को कुरकुरी ओट की परत के साथ जोड़ती है। यह ज़्यादा सेहतमंद संस्करण मधुमेह के अनुकूल है ताकि हर कोई इसका आनंद ले सके।",
"6","1/2 कप",
["3 कप चेरी (ताज़ी या जमी हुई, बीज निकाली हुई)","1 बड़ा चम्मच नीबू का रस","3 बड़े चम्मच शुगर-फ़्री मेपल-टाइप सिरप","1 छोटा चम्मच वेनिला एक्सट्रैक्ट","3/4 कप ओल्ड-फ़ैशन्ड रोल्ड ओट्स","1/4 कप बादाम का आटा","1/4 कप अखरोट (कटे हुए)","2 बड़े चम्मच वनस्पति तेल (पिघला हुआ)","1/4 छोटा चम्मच नमक"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। 9 x 9 इंच के बेकिंग डिश में बेकिंग पेपर बिछाएँ।","एक कटोरे में बीज निकाली हुई चेरी, नीबू का रस, ज़ीरो-कैलोरी मेपल सिरप और वेनिला एक्सट्रैक्ट मिलाएँ। तब तक उछालकर मिलाएँ जब तक चेरी पर अच्छी तरह लग न जाए।","चेरी को तैयार बेकिंग डिश में डालें और एक बराबर परत में फैलाएँ।","एक अलग कटोरे में ओट्स, बादाम का आटा, कटे हुए मेवे, वनस्पति तेल और नमक मिलाएँ। मिश्रण के भुरभुरा होने तक चलाएँ।","ओट्स का मिश्रण चेरी के ऊपर बराबर छिड़कें।","लगभग 30 मिनट बेक करें, या जब तक चेरी का भरावन बुलबुले न छोड़ने लगे और ओट्स की परत सुनहरी भूरी न हो जाए।","परोसने से पहले इसे 10 मिनट ठंडा होने दें।","गरम परोसें।"]))
r.append(R(6549802,"स्मोकी काली बीन्स डिप",
"हमारे स्मोकी काली बीन्स डिप के साथ स्वाद की जन्नत में गोता लगाएँ, एक चटपटा अनुभव जो साधारण काली बीन्स को स्मोकी दावत में बदल देता है। इस डिप को ताज़ी सब्ज़ियों के साथ परोसें, एक सेहतमंद, कम कार्ब वाले स्नैक या स्टार्टर के रूप में जो मधुमेह वाले और बिना मधुमेह वाले दोनों लोगों के लिए एकदम सही है।",
"6","1/4 कप डिप + 1/2 कप कटा हुआ खीरा और शिमला मिर्च",
["1 डिब्बा (15 औंस) काली बीन्स (बिना नमक मिलाई, पानी निथारी और धुली हुई)","2 कली लहसुन (बारीक कटी हुई)","2 बड़े चम्मच नीबू का रस","1 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच स्मोक्ड पैपरिका","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच सादा फ़ैट-फ़्री ग्रीक योगर्ट","3 कप खीरा (स्लाइस किया हुआ)","3 कप लाल शिमला मिर्च (स्लाइस की हुई)"],
["फ़ूड प्रोसेसर में पानी निथारी और धुली हुई काली बीन्स, कटा हुआ लहसुन, कटी हुई ताज़ा धनिया पत्ती, नीबू का रस, पिसा जीरा, स्मोक्ड पैपरिका, नमक और काली मिर्च मिलाएँ। तब तक पीसें जब तक मिश्रण चिकना और मलाईदार न हो जाए। अपनी पसंद की बनावट के लिए पीसते समय धीरे-धीरे 1 बड़ा चम्मच जैतून का तेल डाल सकते हैं। अपनी पसंद के अनुसार तेल की मात्रा बेझिझक बदलें।","पीसने के बाद डिप चखें और मसालों में ज़रूरी बदलाव करें। अपने स्वाद के अनुसार और नमक, काली मिर्च या नीबू का रस डाल सकते हैं।","काली बीन्स डिप को परोसने वाले कटोरे में डालें और उसमें धीरे से 2 बड़े चम्मच सादा ग्रीक योगर्ट घुमाकर मिलाएँ। यह डिप को मलाईदार बनावट और हल्का खट्टापन देता है।","कटे हुए खीरे और शिमला मिर्च के साथ परोसें।"]))
r.append(R(6549854,"टमाटर और टस्कन जड़ी-बूटियों के साथ ग्रिल्ड पोर्टाबेला",
"ये स्वादिष्ट मशरूम ताज़ा मोज़ेरेला या प्रोवोलोन चीज़ के स्लाइस के साथ और साबुत अनाज की ब्रेड पर परोसने पर एक स्वादिष्ट सैंडविच बनाते हैं। साथ में मिली-जुली हरी सब्ज़ियों का सलाद परोसें।",
"6","1 मशरूम कैप",
["1/4 कप एक्स्ट्रा वर्जिन जैतून का तेल","2 बड़े चम्मच नीबू का रस","2 बड़े चम्मच बाल्सैमिक सिरका","1 बड़ा चम्मच ताज़ा ओरेगानो (बारीक कटा हुआ)","1 टहनी ताज़ा रोज़मेरी (बारीक कटी हुई)","2 बड़े चम्मच तुलसी (बारीक कटी हुई)","2 कली लहसुन (बारीक कटी हुई)","1/2 कप टमाटर (कटे हुए)","1/2 छोटा चम्मच काली मिर्च","6 साबुत पोर्टोबेलो मशरूम (पोंछकर साफ़ किए हुए और डंठल निकाले हुए)"],
["मैरिनेड की सारी सामग्री को एक मध्यम कटोरे में मिलाएँ और एक बड़ी कसकर बंद होने वाली प्लास्टिक थैली में डालें। सबसे अच्छे नतीजों के लिए मशरूम कैप को कमरे के तापमान पर कम से कम 15-30 मिनट मैरिनेट करें।","ग्रिल को मध्यम-तेज़ आँच पर पहले से गरम करें और मशरूम कैप को ग्रिल की जाली पर रखें। सीधी आँच पर हर तरफ़ 5 मिनट तक पकाएँ, जब तक वे अंदर तक पूरी तरह नरम न हो जाएँ। पकाते समय बीच-बीच में अतिरिक्त मैरिनेड लगाते रहें। परोसने से पहले बचा हुआ मैरिनेड मशरूम पर डाल सकते हैं।"]))
r.append(R(6550239,"भूनी हुई फ़िश केक",
"सफ़ेद मछली, कॉड या तिलापिया सख़्त सफ़ेद मछलियाँ हैं जिनसे बेहतरीन फ़िश केक बनते हैं। डिजॉन मस्टर्ड और नीबू ताज़ा, खट्टा स्वाद जोड़ते हैं। और ज़्यादा चटपटापन के लिए परोसने से ठीक पहले ऊपर थोड़ा नीबू का रस निचोड़ें।",
"6","1 केक",
["1 पाउंड सफ़ेद मछली (पोंछकर सुखाई हुई, और टुकड़ों में कटी हुई)","1/4 कप सादा दही","1 बड़ा चम्मच डिजॉन मस्टर्ड","1 बड़ा चम्मच नीबू का रस","1/2 छोटा चम्मच नमक","1 छोटा चम्मच नीबू का छिलका (कसा हुआ)","1 बड़ा अंडा (फेंटा हुआ)","1 1/4 कप पैंको ब्रेड क्रम्ब्स (बाँटकर उपयोग)","2 डंठल हरा प्याज़ (स्कैलियन) (बारीक कटे हुए)","1/2 छोटा चम्मच हॉट सॉस","1 बड़ा चम्मच वनस्पति तेल"],
["एक बड़ी कड़ाही को 2/3 भाग तक भरने लायक पानी डालें। मध्यम आँच पर पानी को धीमे उबाल पर लाएँ। मछली डालें और 5 से 7 मिनट धीमी आँच पर पकाएँ, या जब तक मछली पूरी तरह न पक जाए। छेददार चम्मच से मछली के टुकड़े निकालें। मछली को एक मिक्सिंग बाउल में डालें और 5 मिनट ठंडा होने दें।","कटोरे से अतिरिक्त तरल निकाल दें। दही, मस्टर्ड, नीबू का रस, नमक, नीबू का छिलका और अंडा डालकर अच्छी तरह मिलाएँ। ½ कप ब्रेड क्रम्ब्स, हरा प्याज़ और हॉट सॉस डालकर अच्छी तरह मिलाएँ। मछली के मिश्रण से 6 केक बनाएँ। बचे हुए ब्रेड क्रम्ब्स से केक के दोनों तरफ़ हल्की परत चढ़ाएँ। केक को एक प्लेट में रखें और ढककर 30 मिनट रेफ़्रिजरेटर में रखें।","केक को रेफ़्रिजरेटर से निकालें और 5 मिनट रहने दें। एक बड़ी कड़ाही में मध्यम आँच पर तेल गरम करें। केक कड़ाही में डालें और हर तरफ़ लगभग 5 मिनट भूनें, जब तक वे सुनहरे भूरे न हो जाएँ।"]))
r.append(R(6550451,"संतरा, एवोकाडो और प्याज़ के साथ हरा सलाद",
"अपने संतरों के साथ रचनात्मक बनें! अपने स्थानीय बाज़ार में नेवल, वैलेंसिया, कारा कारा या ब्लड ऑरेंज दिखें तो उन्हें आज़माएँ। हर एक का स्वाद थोड़ा अलग और स्वादिष्ट है, लेकिन सभी विटामिन C, फ़ाइबर और अन्य सेहत के लिए अच्छे पोषक तत्वों से भरपूर हैं। अपनी थाली को पूरा करें: इस सलाद को किसी भी ऐसे भोजन में जोड़ें जिसमें सब्ज़ियों की ज़रूरत हो। हमने इसे साउथवेस्ट-स्टाइल टर्की मीटलोफ़ और मसले हुए लाल आलू के साथ जोड़ा है।",
"4","1 1/2 कप",
["1 बड़ा चम्मच नीबू का रस","1 बड़ा चम्मच जैतून का तेल","1 छोटा चम्मच रेड वाइन सिरका","1/8 छोटा चम्मच कम कैलोरी वाला चीनी विकल्प","1/4 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च","2 मध्यम संतरे","4 कप मिली-जुली हरी पत्तेदार सब्ज़ियाँ","1 मध्यम एवोकाडो (गुठली निकाला हुआ और गूदा टुकड़ों में कटा हुआ)","1/4 छोटा लाल प्याज़ (कटा हुआ)","2 बड़े चम्मच ताज़ा धनिया पत्ती (कटी हुई)"],
["एक छोटे कटोरे में नीबू का रस, जैतून का तेल, रेड वाइन सिरका, चीनी विकल्प, कोशर नमक और काली मिर्च को फेंटकर मिलाएँ।","संतरों के चारों ओर से छिलका और सफ़ेद परत हटा दें। छोटे चाकू से झिल्लियों के बीच काटकर संतरे की फाँकें अलग करें और उन्हें तीन टुकड़ों में काटें। संतरे के टुकड़ों को एक मध्यम कटोरे में रखें।","कटोरे में मिली-जुली हरी पत्तेदार सब्ज़ियाँ, एवोकाडो के टुकड़े और लाल प्याज़ डालें और ऊपर से नीबू के रस का मिश्रण डालें। मिलाने के लिए उछालें। धनिया पत्ती छिड़ककर परोसें।"]))
r.append(R(6551080,"पोब्लानो सॉस के साथ चिली लाइम झींगा",
"पोब्लानो सॉस के साथ चिली लाइम झींगा एक स्वादिष्ट और चटपटा व्यंजन है जो मिर्चों की तीव्रता, नीबू की खटास और पोब्लानो मिर्च की स्मोकी खुशबू को मिलाता है।",
"6","1/4 पाउंड झींगे",
["1 साबुत पोब्लानो मिर्च","3 कली लहसुन (बाँटकर उपयोग)","1/2 कप सादा फ़ैट-फ़्री ग्रीक योगर्ट","1 छोटा चम्मच पिसा जीरा","1/8 छोटा चम्मच कोशर नमक","1 पाउंड झींगे (केवल पूँछ छोड़कर छिले हुए और नस निकाले हुए)","1 बड़ा चम्मच जैतून का तेल","1 साबुत सेरानो मिर्च (स्लाइस की हुई)","1/4 छोटा चम्मच काली मिर्च"],
["शीट पैन पर बेकिंग पेपर बिछाएँ और ब्रॉयलर को तेज़ पर पहले से गरम करें। पोब्लानो मिर्च को हल्का काला होने तक लगभग 5 मिनट ब्रॉइल करें, दो-तीन बार पलटें। इसे एक कटोरे में रखें और प्लास्टिक रैप से ढककर 5 मिनट भाप में रहने दें।","जब वह छूने लायक ठंडी हो जाए, तो छिलका उतार दें। डंठल हटाएँ और मिर्च को चीरकर बीज निकालें और मिर्च को मोटा-मोटा काट लें।","झींगों को ½ बड़ा चम्मच जैतून का तेल, 1 कली लहसुन, मिर्चों और काली मिर्च के साथ मिलाएँ। इसे 15-30 मिनट मैरिनेट होने दें","जब झींगे मैरिनेट हो रहे हों, सॉस तैयार करें। पोब्लानो मिर्च, ग्रीक योगर्ट, 2 कसी हुई लहसुन की कलियाँ, जीरा, कोशर नमक और काली मिर्च को फ़ूड प्रोसेसर में चिकना होने तक पीसें।","एक कड़ाही में बचा हुआ ½ बड़ा चम्मच जैतून का तेल गरम करें। कड़ाही गरम होने पर झींगों को हर तरफ़ 2 मिनट तक सेकें, जब तक वे बस पक न जाएँ।","पोब्लानो सॉस के साथ परोसें।"]))
r.append(R(6551436,"किफ़ायती जड़ी-बूटी लहसुन मीटलोफ़",
"यह स्वादिष्ट किफ़ायती मीटलोफ़ क्लासिक मीटलोफ़ जितना ही अच्छा है। हमारा मधुमेह के अनुकूल संस्करण कम चर्बी वाली कीमा टर्की से बनता है और ताज़ी जड़ी-बूटियों और लहसुन से मसालेदार बनाया जाता है। संपूर्ण भोजन के लिए इसे भुने हुए शकरकंद (वे ओवन में मीटलोफ़ के साथ ही भुन सकते हैं) और बिना स्टार्च वाली सब्ज़ी की साइड या सादे हरे सलाद के साथ परोसें।\n\nPowered by Homemade",
"6","1 स्लाइस",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 स्लाइस साबुत गेहूँ की ब्रेड","1/4 कप अंडे का विकल्प","20 औंस कम चर्बी वाली कीमा टर्की","2 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच ताज़ा ओरेगानो","1 बड़ा चम्मच ताज़ी तुलसी (कटी हुई)","1/2 कप केचप (बाँटकर उपयोग)","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च","2 बड़े चम्मच बाल्सैमिक सिरका"],
["ओवन को 375 डिग्री F पर पहले से गरम करें। लोफ़ पैन पर कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","एक मध्यम कटोरे में साबुत गेहूँ की ब्रेड के टुकड़े को मटर के दाने जितने टुकड़ों में तोड़ें। अंडा डालकर अच्छी तरह मिलाएँ।","टर्की, लहसुन, ओरेगानो, तुलसी, 1/4 कप केचप, नमक (वैकल्पिक) और पिसी काली मिर्च डालें। अच्छी तरह मिलाएँ।","टर्की के मिश्रण को लोफ़ पैन में कसकर दबाएँ। 20 मिनट बेक करने के लिए ओवन में रखें।","जब मीटलोफ़ बेक हो रहा हो, बचा हुआ 1/4 कप केचप, बाल्सैमिक सिरका और हॉट सॉस (वैकल्पिक) फेंटकर मिलाएँ।","मीटलोफ़ को 20 मिनट बेक करने के बाद उस पर केचप और बाल्सैमिक ग्लेज़ डालें। 15 मिनट और बेक करने के लिए वापस ओवन में रखें, या जब तक मीटलोफ़ का अंदरूनी तापमान 165 डिग्री F न हो जाए।","मीटलोफ़ को 10 मिनट रहने दें, फिर 6 बराबर भागों में काटें।"]))
r.append(R(6551703,"हार्वेस्ट सलाद कैसे बनाएँ",None,
"4","1/2 कप",
["1/4 कप सेब का सिरका","1/4 छोटा चम्मच नमक","1 छोटा चम्मच डिजॉन मस्टर्ड","2 बड़े चम्मच जैतून का तेल","1 1/2 बड़े चम्मच ताज़ा पुदीना (पत्तियाँ, बारीक कटी हुई और सजाने के लिए थोड़ी और)","12 औंस मिली-जुली हरी पत्तेदार सब्ज़ियाँ (1 बैग, मिक्स्ड बेबी)","2 साबुत मूली (पतले स्लाइस में कटी हुई)","1/2 कप शुगर स्नैप मटर (1/2 इंच के टुकड़ों में कटे हुए)","1/8 छोटा चम्मच काली मिर्च (ताज़ी पिसी हुई, स्वादानुसार)","4 बड़े चम्मच पेपिटास (भुने हुए)","2 बड़े चम्मच अनार के दाने"],
["सेब के सिरके की विनेग्रेट बनाने के लिए: सेब का सिरका एक कटोरे या ढक्कन वाले छोटे जार में डालें। ¼ छोटा चम्मच नमक डालें और मिलाने के लिए हिलाएँ या फेंटें।","डिजॉन मस्टर्ड और जैतून का तेल डालें और ज़ोर से हिलाएँ या अच्छी तरह फेंटकर मिलाएँ।","ताज़ा कटा हुआ पुदीना सलाद पर ड्रेसिंग डालने से ठीक पहले डालें (नहीं तो वह भूरा हो जाएगा)।","सलाद बनाने के लिए: एक बड़े कटोरे में हरी पत्तेदार सब्ज़ियाँ, मूली, शुगर स्नैप मटर, आधे पेपिटास और आधे अनार के दाने मिलाएँ।","ड्रेसिंग के कुछ बड़े चम्मच डालकर उछालें। हरी पत्तियों पर बस हल्की सी ड्रेसिंग लगनी चाहिए।","चखें और ज़रूरत के अनुसार ताज़ी पिसी काली मिर्च डालें। परोसने से पहले बचे हुए पेपिटास और अनार के दानों से सजाएँ।"]))
r.append(R(6551725,"कद्दू-वेनिला पुडिंग",
"पतझड़ के गरम मसाले इस मलाईदार पुडिंग को एक उत्सवी त्योहारी मिठाई बनाते हैं!",
"8","1/2 कप",
["1/4 कप कम कैलोरी वाला चीनी विकल्प","2 बड़े चम्मच कॉर्नस्टार्च","1 3/4 कप 1% दूध","2 बड़े अंडे","8 औंस डिब्बाबंद कद्दू","1 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच पिसी लौंग","1/4 छोटा चम्मच पिसी अदरक","1/8 छोटा चम्मच पिसा जायफल","1 साबुत वेनिला बीन","1/4 कप पीकन","8 बड़े चम्मच व्हिप्ड टॉपिंग (लाइट)"],
["3 क्वार्ट के सॉसपैन में चीनी विकल्प और कॉर्नस्टार्च को फेंटकर मिलाएँ।","एक छोटे कटोरे में दूध और अंडे की ज़र्दी को फेंटकर मिलाएँ। मध्यम आँच पर अंडे के मिश्रण को धीरे-धीरे चीनी वाले मिश्रण में फेंटते हुए डालें। उबाल आने तक मिश्रण को फेंटते रहें जब तक वह गाढ़ा न हो जाए, लगभग 3 से 5 मिनट।","कद्दू, दालचीनी, लौंग, अदरक और जायफल डालें। अच्छी तरह मिलाएँ और धीमी आँच पर 3 मिनट पकाएँ। वेनिला बीन के बीज डालें और 1 मिनट और पकाएँ।","सॉसपैन को चूल्हे से उतार लें। पुडिंग को एक कटोरे में रखें और प्लास्टिक रैप से ढक दें। परोसने से पहले 1 घंटे रेफ़्रिजरेटर में रखें। परोसने के लिए पुडिंग को अलग-अलग कटोरियों में चम्मच से डालें, हर कटोरी के ऊपर 1/2 बड़ा चम्मच पीकन डालें और ऊपर से दालचीनी छिड़कें। चाहें तो ऊपर व्हिप्ड टॉपिंग की एक डली रखें।"]))
r.append(R(6552861,"शहद-सरसों के साथ भुनी हुई ब्रसेल्स स्प्राउट्स",
"सब्ज़ियों को भूनने से उनकी प्राकृतिक शर्करा सतह पर आ जाती है जिससे वे कम कड़वी और स्वादिष्ट हो जाती हैं। शहद-सरसों का सॉस इन ब्रसेल्स स्प्राउट्स में एक मीठा खट्टापन जोड़ता है।",
"9","1 कप",
["2 पाउंड ब्रसेल्स स्प्राउट्स (निचला हिस्सा कटा हुआ)","2 बड़े चम्मच जैतून का तेल","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच दरदरी डिजॉन मस्टर्ड","1 बड़ा चम्मच शहद"],
["ओवन को 425°F पर पहले से गरम करें। एक चपटी बेकिंग शीट पर बेकिंग पेपर बिछाएँ।","कटे हुए स्प्राउट्स को एक बड़े कटोरे में जैतून का तेल, नमक और काली मिर्च के साथ मिलाएँ। स्प्राउट्स को बेकिंग पेपर बिछी बेकिंग शीट पर एक ही परत में रखें।","ब्रसेल्स स्प्राउट्स को लगभग 45 मिनट तक या कुरकुरा होने तक भूनें, लगभग हर 15 मिनट में शीट को हिलाएँ।","एक छोटे कटोरे में सरसों और शहद को मिलाएँ। जब स्प्राउट्स तैयार हो जाएँ, तो उन्हें परोसने वाले कटोरे में डालें। शहद-सरसों का मिश्रण डालें और अच्छी तरह मिलाएँ। तुरंत परोसें।"]))
r.append(R(6553465,"दालचीनी सेब ओटमील",
"ताज़े सेब इस ओटमील को पतझड़ के नाश्ते के लिए एकदम सही बनाते हैं। मसालों की एक छिड़कन इस मधुमेह के अनुकूल दालचीनी सेब ओटमील में गहराई भरा स्वाद जोड़ती है, जो पूरे परिवार को पसंद आएगा।",
"4","1/2 कप ओट्स + 1/4 सेब",
["1 कप ओल्ड-फ़ैशन्ड रोल्ड ओट्स (सूखे)","2 कप पानी","1 कप स्किम दूध","1 मध्यम सेब (छिला, बीज निकाला, टुकड़ों में कटा हुआ)","1 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच पिसा जायफल","1/4 छोटा चम्मच नमक"],
["एक सॉसपैन में पानी उबालें।","ओट्स डालकर चलाएँ और आँच को मध्यम-धीमा कर दें। बीच-बीच में चलाते हुए लगभग 5 मिनट पकाएँ, या जब तक ओट्स गाढ़े होने न लगें।","दूध, कटा हुआ सेब, दालचीनी, जायफल और नमक डालें। बार-बार चलाते हुए तब तक पकाना जारी रखें जब तक ओट्स मलाईदार और सेब नरम न हो जाएँ (लगभग 5 मिनट और)।","आँच से उतारें और गाढ़ा होने के लिए एक मिनट रहने दें।","ओटमील को दो कटोरों में बाँटें। गरम परोसें।"]))
r.append(R(6553525,"ताज़ा अदरक की ड्रेसिंग के साथ चिकन केल सलाद",
"यह तेज़ और आसान सलाद बस कुछ सामग्री से झटपट तैयार हो जाता है, संतुलित और जल्दी बनने वाले दोपहर के भोजन या साइड डिश के लिए एकदम सही।",
"4","2 कप सलाद + 3 औंस पका हुआ चिकन + 3 बड़े चम्मच ड्रेसिंग",
["1 पाउंड बिना हड्डी और बिना त्वचा वाली चिकन ब्रेस्ट","8 कप मिली-जुली हरी पत्तेदार सब्ज़ियाँ (बेबी केल की पत्तियों के साथ कसकर भरा पालक)","3/4 कप लाइट रास्पबेरी सलाद ड्रेसिंग","2 छोटे चम्मच ताज़ा अदरक (कसा हुआ)"],
["ग्रिल या ग्रिल पैन को मध्यम-तेज़ आँच पर गरम करें। चिकन पर कुकिंग स्प्रे लगाएँ, चाहें तो 1/4 छोटा चम्मच नमक और 1/4 छोटा चम्मच काली मिर्च छिड़कें। हर तरफ़ 6 मिनट पकाएँ या जब तक बीच से गुलाबी रंग न रहे। ठंडा होने दें और पतले स्लाइस में काटें।","चार डिनर प्लेटों पर हरी पत्तेदार सब्ज़ियाँ और चिकन बराबर मात्रा में रखें। सलाद ड्रेसिंग और अदरक को अच्छी तरह मिलने तक फेंटें। सब पर बराबर मात्रा में चम्मच से डालें।"]))
save(3,r)
